using System.ComponentModel;
using System.Text.Json;

namespace ResearchAgent;

/// <summary>
/// Tools available to the research agent for searching the web and taking notes.
/// </summary>
public sealed class ResearchTools
{
    private readonly List<NoteEntry> _notes = [];
    private readonly HttpClient _httpClient;

    public ResearchTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public IReadOnlyList<NoteEntry> Notes => _notes;

    [Description("Search the web for information on a given query. Returns a list of search result snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query string")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);

        try
        {
            var encodedQuery = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encodedQuery}&format=json&no_redirect=1&no_html=1";

            var response = await _httpClient.GetAsync(url);
            response.EnsureSuccessStatusCode();

            var json = await response.Content.ReadAsStringAsync();
            var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<SearchResult>();

            // Extract the abstract if available
            if (root.TryGetProperty("Abstract", out var abstractText) &&
                abstractText.GetString() is { Length: > 0 } abs)
            {
                var source = root.TryGetProperty("AbstractSource", out var src) ? src.GetString() ?? "" : "";
                var absUrl = root.TryGetProperty("AbstractURL", out var au) ? au.GetString() ?? "" : "";
                results.Add(new SearchResult(source, abs, absUrl));
            }

            // Extract related topics
            if (root.TryGetProperty("RelatedTopics", out var topics) &&
                topics.ValueKind == JsonValueKind.Array)
            {
                foreach (var topic in topics.EnumerateArray())
                {
                    if (results.Count >= maxResults)
                        break;

                    if (topic.TryGetProperty("Text", out var text) &&
                        text.GetString() is { Length: > 0 } t)
                    {
                        var topicUrl = topic.TryGetProperty("FirstURL", out var fu)
                            ? fu.GetString() ?? "" : "";
                        results.Add(new SearchResult("DuckDuckGo", t, topicUrl));
                    }
                }
            }

            if (results.Count == 0)
            {
                return $"No results found for '{query}'. Try rephrasing or using different keywords.";
            }

            return JsonSerializer.Serialize(results, JsonSerializerOptions.Web);
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed: {ex.Message}. Try again or use a different query.";
        }
    }

    [Description("Save a research note with a title and content. Use this to record important findings during research.")]
    public string SaveNote(
        [Description("Short title for the note")] string title,
        [Description("The content/body of the note")] string content,
        [Description("Source URL or reference, if any")] string? source = null)
    {
        var entry = new NoteEntry(
            Id: _notes.Count + 1,
            Title: title,
            Content: content,
            Source: source,
            Timestamp: DateTimeOffset.UtcNow);

        _notes.Add(entry);
        return $"Note #{entry.Id} saved: \"{title}\"";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return JsonSerializer.Serialize(_notes, JsonSerializerOptions.Web);
    }

    public record SearchResult(string Source, string Snippet, string Url);

    public record NoteEntry(int Id, string Title, string Content, string? Source, DateTimeOffset Timestamp);
}

