using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;
using ResearchAgent;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");
var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- DI container ---
var services = new ServiceCollection();

services.AddLogging(builder => builder
    .AddConsole()
    .SetMinimumLevel(LogLevel.Warning));

services.AddHttpClient<ResearchTools>();

services.AddSingleton<ResearchTools>();

// Register the chat client via MEAI abstraction
services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

var provider = services.BuildServiceProvider();

// --- Build tools from ResearchTools ---
var tools = provider.GetRequiredService<ResearchTools>();
var aiTools = new AITool[]
{
    AIFunctionFactory.Create(tools.SearchWebAsync),
    AIFunctionFactory.Create(tools.SaveNote),
    AIFunctionFactory.Create(tools.GetNotes),
};

// --- Build the agent ---
var chatClient = provider.GetRequiredService<IChatClient>();

var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. Your job is to thoroughly research a topic the user provides.

        Follow this workflow:
        1. Break the topic into 2-3 focused sub-questions.
        2. Use SearchWebAsync to search for information on each sub-question.
        3. Use SaveNote to record key findings with source attribution.
        4. After gathering enough information, use GetNotes to review all your notes.
        5. Provide a well-structured summary with sections and source references.

        Guidelines:
        - Always cite sources when saving notes.
        - Save at least 2-3 notes before summarizing.
        - If a search returns no results, rephrase and try again.
        - Be thorough but concise in your final summary.
        """,
};

// --- Run the agent ---
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent             ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine();
Console.WriteLine($"Researching: {topic}");
Console.WriteLine(new string('─', 40));

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
        Tools = [.. aiTools],
    },
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
